      spec,
      homeDir: _homeDir,
      workspaceRoot: _delegate.cwd,
    );
  }

  /// Leaves sandbox mode: every operation forwards untouched.
  void clearSpec() {
    _shellSpec = null;
    _guard = null;
    _engine = null;
    _shell.clearSpec();
  }

