    final memory = spec.resources.memoryBytes;
    if (memory != null) {
      parts.add('ulimit -v ${(memory + 1023) ~/ 1024};');
    }
    final timeout = spec.resources.timeout;
    if (timeout != null) {
      parts.add('ulimit -t ${timeout.inSeconds};');
    }
